		var body map[string]interface{}
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}
		valFloat, ok := body["message"].(float64)
		if !ok {
			return errBadValue
		}
		val := int(valFloat)

		// Acknowledge immediately
		if err := n.Reply(msg, map[string]interface{}{
			"type": "broadcast_ok",
		}); err != nil {
			return err
		}

		state.propagate(n, val, "")
		return nil
